general_comments.body:
Actually I could add following unit test for this PR. It simulates old WebKit DOM collection so we can reproduce this issue even in new Chrome. It is a bit tricky though so please let me know what do you think.
```javascript
QUnit.test( "jQuery should not classify DOM collection as a function (#gh-4756)", function( assert ) {
	assert.expect( 4 );

	// Simulate DOMCollection object from WebKit 534.34 with 3 elements
	// 1. Should be mistaken with function, i.e. typeof obj === "function"
	function obj( a, b, c ) { }
	// 2. Should have length
	assert.equal( obj.length, 3, "Collection length should be 3." );
	// 3. Should be like collection, i.e. typeof obj.item === "function"
	obj.item = function( i ) { return obj[ i ]; };
	// 4. Should have 3 valid items
	obj[ 0 ] = obj[ 1 ] = obj[ 2 ] = 0;

	// Call isFunction( obj ) through isArrayLike
	jQuery.each( obj, function( i, x ) { assert.equal( x, obj[ i ], "Could read element at index: " + i ); } );
} );
```
Without fix:
![image](https://user-images.githubusercontent.com/37873210/88585481-71e64200-d053-11ea-8ab7-abea33862183.png)

With fix:
![image](https://user-images.githubusercontent.com/37873210/88586322-8971fa80-d054-11ea-96ee-c8c8c2af3c12.png)

